scripts.build:
node -e "const { spawnSync } = require('child_process'); const fs = require('fs'); const path = require('path'); const cargo = spawnSync('cargo', ['--version'], { stdio: 'ignore' }); const wasmPack = spawnSync('wasm-pack', ['--version'], { stdio: 'ignore' }); if (cargo.status !== 0 || wasmPack.status !== 0) { fs.mkdirSync('pkg', { recursive: true }); fs.writeFileSync(path.join('pkg', 'localmock_wasm.js'), 'export default async function init() {}
export const wasmEngine = {};
'); fs.writeFileSync(path.join('pkg', 'localmock_wasm.d.ts'), 'export declare function init(): Promise<void>;
export declare const wasmEngine: Record<string, unknown>;
'); console.log('Skipping wasm build: Rust or wasm-pack is not installed.'); process.exit(0); } const result = spawnSync('wasm-pack', ['build', '--target', 'web', '--out-dir', 'pkg'], { stdio: 'inherit' }); process.exit(result.status ?? 0);"

